package com.nigson.commerce.quote;

import java.time.*;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.platform.*;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.order.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;

/** Quote commands execute in Commerce transactions; Experience calls happen only after commit. */
public final class QuoteService {
 private final QuoteRepository repo;private final PricingAuthority authority;private final QuoteLeadPort leads;private final PlatformStore commands;private final AuditWriter audit;private final JdbcTemplate jdbc;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;private final CheckoutQuoteRepository checkoutQuotes;private final OrderService orders;
 public QuoteService(QuoteRepository repo,PricingAuthority authority,QuoteLeadPort leads,PlatformStore commands,AuditWriter audit,JdbcTemplate jdbc,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics,CheckoutQuoteRepository checkoutQuotes,OrderService orders){this.repo=repo;this.authority=authority;this.leads=leads;this.commands=commands;this.audit=audit;this.jdbc=jdbc;this.clock=clock;this.metrics=metrics;this.checkoutQuotes=checkoutQuotes;this.orders=orders;}
 private void limits(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private QuoteValues.Quote replay(ActorAssertion.Actor actor,String role,String api,String key,Object body){authority.require(actor,role);ApiValues.idempotencyKey(key);if(!commands.completed(actor.party().toString(),api,key))return null;var response=commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);});return repo.current(response.resource());}
 private QuoteValues.Quote command(ActorAssertion.Actor actor,String role,String api,String key,Object body,UUID correlation,AuditValues.Action action,java.util.function.Supplier<QuoteValues.Quote> change,boolean event){authority.require(actor,role);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();try{var response=commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{limits();authority.stabilize(actor,role);var after=change.get();audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,AuditValues.Resource.QUOTE,after.id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state",after.state(),"version",after.version(),"revision",after.revision()),null);if(event)offered(after,correlation,actor.party().toString());TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.quote.commands","operation",switch(api){case "API-068"->"CREATE";case "API-069"->"REVISE";case "API-070"->"OFFER";case "API-173"->"APPROVE";default->"OTHER";}).increment();}});return new PlatformStore.Response(api.equals("API-068")||api.equals("API-069")?201:200,EventCodec.JSON.valueToTree(after),after.id());});return EventCodec.JSON.treeToValue(response.body(),QuoteValues.Quote.class);}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 public QuoteValues.Quote create(ActorAssertion.Actor actor,QuoteValues.CreateInput input,String key,UUID correlation){authority.require(actor,"SALES");if(input==null)throw ApiValues.invalid();Object body=input;var prior=replay(actor,"SALES","API-068",key,body);if(prior!=null){UUID leadId=jdbc.queryForObject("SELECT source_lead_id FROM commerce.quote WHERE id=?",UUID.class,prior.id());associate(actor,leadId,prior.id(),prior.revisionId(),"DRAFT",key,correlation);return prior;}var lead=leads.context(input.sourceLeadId(),correlation);if(!input.partyId().equals(lead.partyId())||!Objects.equals(input.organizationId(),lead.organizationId())||!Set.of("NEW","ASSIGNED","IN_PROGRESS").contains(lead.state()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);var result=command(actor,"SALES","API-068",key,input,correlation,AuditValues.Action.QUOTE_CREATE,()->repo.create(actor,input,actor.party().toString()),false);associate(actor,input.sourceLeadId(),result.id(),result.revisionId(),"DRAFT",key,correlation);return result;}
 public QuoteValues.Quote revise(ActorAssertion.Actor actor,UUID id,long version,QuoteValues.RevisionInput input,String key,UUID correlation){if(id==null||id.equals(new UUID(0,0)))throw ApiValues.invalid();Object body=Map.of("id",id,"version",version,"body",input);var prior=replay(actor,"SALES","API-069",key,body);return prior==null?command(actor,"SALES","API-069",key,body,correlation,AuditValues.Action.QUOTE_REVISION,()->repo.revise(actor,id,version,input,actor.party().toString()),false):prior;}
 public QuoteValues.Quote approve(ActorAssertion.Actor actor,UUID id,UUID revision,long version,QuoteValues.Decision input,String key,UUID correlation){if(id==null||revision==null||id.equals(new UUID(0,0))||revision.equals(new UUID(0,0)))throw ApiValues.invalid();Object body=Map.of("id",id,"revisionId",revision,"version",version,"body",input);var prior=replay(actor,"FINANCE","API-173",key,body);return prior==null?command(actor,"FINANCE","API-173",key,body,correlation,AuditValues.Action.QUOTE_APPROVAL,()->repo.approve(actor,id,revision,version,input,actor.party().toString()),false):prior;}
 public QuoteValues.Quote offer(ActorAssertion.Actor actor,UUID id,long version,QuoteValues.Offer input,String key,UUID correlation){if(id==null||id.equals(new UUID(0,0)))throw ApiValues.invalid();Object body=Map.of("id",id,"version",version,"body",input);var prior=replay(actor,"SALES","API-070",key,body);var result=prior==null?command(actor,"SALES","API-070",key,body,correlation,AuditValues.Action.QUOTE_OFFER,()->repo.offer(actor,id,version,input,actor.party().toString()),true):prior;UUID lead=jdbc.queryForObject("SELECT source_lead_id FROM commerce.quote WHERE id=?",UUID.class,result.id());associate(actor,lead,result.id(),result.revisionId(),"OFFERED",key,correlation);return result;}
 public QuoteValues.Quote get(ActorAssertion.Actor actor,UUID id){return repo.get(actor,id);}
 public OrderValues.Checkout accept(ActorAssertion.Actor actor,UUID id,long expected,QuoteValues.AcceptInput input,String key,UUID correlation){authority.require(actor,"CUSTOMER");repo.requireOwner(actor,id);if(id==null||id.equals(new UUID(0,0))||expected<0||expected==Long.MAX_VALUE||input==null||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var body=Map.of("id",id,"version",expected,"body",input);var response=commands.executeLocal(actor.party().toString(),"API-072",key,EventCodec.JSON.valueToTree(body),db->{limits();authority.stabilize(actor,"CUSTOMER");var quote=repo.owned(id,input.revisionId(),actor,true);if(quote.version()!=expected&&!(quote.state().equals("ACCEPTED")&&quote.version()==expected+1))throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(quote.state().equals("ACCEPTED")){UUID existingOrder=jdbc.queryForObject("SELECT accepted_order_id FROM commerce.quote WHERE id=?",UUID.class,id);if(existingOrder==null)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var existing=jdbc.queryForList("SELECT id FROM commerce.sales_order WHERE id=? AND accepted_quote_revision_id=?",existingOrder,input.revisionId());if(existing.size()!=1)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(Map.of("orderId",existingOrder)),existingOrder);}var carriers=jdbc.queryForList("SELECT cart_id,source_quote_revision_id FROM commerce.carrier_quote WHERE id=? AND status='QUOTED' AND expires_at>? FOR UPDATE",input.carrierQuoteId(),Timestamp.from(clock.instant()));if(carriers.size()!=1||!input.revisionId().equals(carriers.getFirst().get("source_quote_revision_id")))throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID cart=(UUID)carriers.getFirst().get("cart_id");var cartOwner=jdbc.queryForList("SELECT party_id,organization_id,market_id FROM commerce.cart WHERE id=? AND status='ACTIVE' FOR UPDATE",cart);if(cartOwner.size()!=1||!actor.party().equals(cartOwner.getFirst().get("party_id")))throw new Problem.Failure(ProblemCode.NOT_FOUND);var checkout=checkoutQuotes.create(actor,new PricingValues.QuoteInput(cart,input.addressId(),input.carrierQuoteId(),null));var result=orders.pending(actor,new OrderValues.CheckoutInput(checkout.id(),checkout.quoteHash(),"HOSTED"),correlation);if(jdbc.update("UPDATE commerce.quote SET status='ACCEPTED',accepted_order_id=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=? AND status='OFFERED' AND current_revision_id=?",result.order().id(),Timestamp.from(clock.instant()),actor.party().toString(),id,expected,input.revisionId())!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUOTE_ACCEPT,AuditValues.Resource.QUOTE,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("version",quote.version(),"revision",quote.revision()),Map.of("state","ACCEPTED","version",quote.version()+1,"revision",quote.revision()),null);accepted(quote,result.order().id(),correlation,actor.party().toString());TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.quote.commands","operation","ACCEPT").increment();}});return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(Map.of("orderId",result.order().id())),result.order().id());});UUID order=response.body().has("orderId")?ApiValues.uuid(response.body().path("orderId").asString()):response.resource();OrderValues.Checkout result=new OrderValues.Checkout(orders.get(actor,order),null);var progressed=orders.progress(actor,order,correlation);UUID lead=jdbc.queryForObject("SELECT source_lead_id FROM commerce.quote WHERE id=?",UUID.class,id);associate(actor,lead,id,input.revisionId(),"ACCEPTED",key,correlation);return progressed;}
 private void associate(ActorAssertion.Actor actor,UUID lead,UUID quote,UUID revision,String state,String key,UUID correlation){UUID command=UUID.nameUUIDFromBytes(("quote-association:"+actor.party()+":"+quote+":"+revision+":"+state+":"+key).getBytes(StandardCharsets.UTF_8));if(!leads.associate(lead,command,quote,state,correlation))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
 private void offered(QuoteValues.Quote quote,UUID correlation,String actor){var row=jdbc.queryForMap("SELECT source_lead_id,organization_id FROM commerce.quote WHERE id=?",quote.id());var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id",EventCodec.uuid7(clock.instant()));envelope.put("event_type","quote.offered.v1");envelope.put("schema_version",1);envelope.put("producer","commerce");envelope.put("occurred_at",clock.instant());envelope.put("aggregate_id",quote.id());envelope.put("aggregate_version",quote.version());envelope.put("organization_id",row.get("organization_id"));envelope.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();envelope.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);envelope.put("payload",Map.of("quote_id",quote.id(),"revision_id",quote.revisionId(),"lead_id",row.get("source_lead_id")));commands.append(EventCodec.JSON.writeValueAsString(envelope),actor);}
 private void accepted(QuoteValues.Quote quote,UUID order,UUID correlation,String actor){var row=jdbc.queryForMap("SELECT source_lead_id,organization_id FROM commerce.quote WHERE id=?",quote.id());var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id",EventCodec.uuid7(clock.instant()));envelope.put("event_type","quote.accepted.v1");envelope.put("schema_version",1);envelope.put("producer","commerce");envelope.put("occurred_at",clock.instant());envelope.put("aggregate_id",quote.id());envelope.put("aggregate_version",quote.version()+1);envelope.put("organization_id",row.get("organization_id"));envelope.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();envelope.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);envelope.put("payload",Map.of("quote_id",quote.id(),"revision_id",quote.revisionId(),"order_id",order,"lead_id",row.get("source_lead_id")));commands.append(EventCodec.JSON.writeValueAsString(envelope),actor);}
}
